<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref,watch,nextTick} from 'vue';
import Fields from './Fields.vue';
import ImagePicker from './ImagePicker.vue';import ImageGallery from './ImageGallery.vue';import AppearanceSettings from './AppearanceSettings.vue';import ThemeSwitch from './ThemeSwitch.vue';import {backgroundValue,themeValue,savedTheme} from './appearance';
import AccountPanel from './AccountPanel.vue';import ResponsiveBackground from './ResponsiveBackground.vue';import WorkspaceNav from './WorkspaceNav.vue';import CodeUsage from './CodeUsage.vue';
import PaymentOptions from './PaymentOptions.vue';
import OrderPayment from './OrderPayment.vue';
import AdminReview from './AdminReview.vue';
import AdminTeam from './AdminTeam.vue';
import OperationalHistory from './OperationalHistory.vue';
import TelegramPanel from './TelegramPanel.vue';
import SubscriptionsPanel from './SubscriptionsPanel.vue';
import ClientHelp from './ClientHelp.vue';
import PlanCatalog from './PlanCatalog.vue';import {defaultCatalogGuide} from './catalogGuide';
import PlanProtocolPicker from './PlanProtocolPicker.vue';import ConfirmRecordAction from './ConfirmRecordAction.vue';import {configuredProtocols} from './planProtocols';
import AccountDeletion from './AccountDeletion.vue';
import {fields,defaults,localDate} from './schema';
import {traffic,money,date,states,buyKey} from './lib';
type Row=Record<string,any>;
const user=ref<Row|null>(null),csrf=ref(''),page=ref('overview'),busy=ref(false),error=ref(''),notice=ref('');
const branding=ref<Row>({title:'星枢用户中心',traffic_unit:'GB',announcements:[]}),catalog=ref<Row>({plans:[],categories:[]}),orders=ref<Row[]>([]),service=ref<Row|null>(null),devices=ref<Row[]>([]),tickets=ref<Row[]>([]),rows=ref<Row[]>([]),groups=ref<Row[]>([]),categories=ref<Row[]>([]),version=ref<Row>({}),capacity=ref<Row>({}),config=ref<Row|null>(null);
const authMode=ref('login'),auth=reactive({email:'',password:'',name:'',invitation:'',token:'',password_confirm:''});
const authOpen=ref(false),pendingPlan=ref<Row|null>(null),mediaUploads=ref(0),userTheme=ref(savedTheme()),settingsTab=ref('access');
const backgroundReload=ref(0);
const navigation=ref<InstanceType<typeof WorkspaceNav>>(),navigationToggle=ref<HTMLButtonElement>(),navigationState=ref({narrow:false,open:false,collapsed:false}),usageTarget=ref<Row|null>(null);
const guestCatalog=computed(()=>!user.value&&!!branding.value.show_catalog&&!authOpen.value);
const appearance=computed(()=>admin.value&&page.value==='appearance'?settingsForm.value:branding.value);
const effectiveTheme=computed(()=>themeValue(admin.value&&page.value==='appearance'?settingsForm.value.theme:userTheme.value||branding.value.theme));
const desktopBackground=computed(()=>backgroundValue(appearance.value.background_desktop)),mobileBackground=computed(()=>backgroundValue(appearance.value.background_mobile)||desktopBackground.value);
function closeModal(){if(mediaUploads.value)return;editor.value='';selectedPlan.value=null;thread.value=null}
function mediaBusy(value:boolean){mediaUploads.value=Math.max(0,mediaUploads.value+(value?1:-1))}
watch(userTheme,value=>{try{if(value)localStorage.setItem('starhub.portal.theme',value);else localStorage.removeItem('starhub.portal.theme')}catch{}});
const admin=computed(()=>user.value?.role==='admin');
const can=(scope:string)=>!!user.value?.is_owner||!!user.value?.admin_scopes?.includes(scope);
const tabs=computed(()=>admin.value?[
 ['overview','概览','◈',''],['plans','套餐管理','▦','plans'],['catalog','套餐展示预览','▦','plans'],['categories','套餐分类','▤','plans'],['customers','用户与审核','♙','customers'],['orders','订单与开通','▣','orders'],['manual-payments','人工核款','✓','payments'],['coupons','优惠码','◇','coupons'],['invitations','注册邀请','✉','invitations'],['announcements','公告','◎','announcements'],['tickets','服务工单','☏','support'],['payment-methods','收款方式','▧','owner'],['administrators','管理员','♙','owner'],['telegram','Telegram 机器人','✉','owner'],['settings','系统设置','⚙','owner'],['appearance','外观与主题','◐','owner'],['version','版本与更新','↻','owner'],['jobs','后台任务','⋯','jobs'],['audit','操作记录','≡','audit'],['help','客户端教程','?',''],['account','个人账户','○','']
].filter(t=>!t[3]||(t[3]==='owner'?user.value?.is_owner:can(t[3]))):[['overview','我的服务','◈'],['catalog','选购套餐','▦'],['orders','我的订单','▣'],['subscription','订阅与设备','↗'],['tickets','服务工单','☏'],['help','客户端教程','?'],['account','个人账户','○']]);
const navSections=computed(()=>{if(!admin.value)return [{name:'我的服务',items:tabs.value}];const sections=[{name:'工作台',ids:['overview']},{name:'套餐与销售',ids:['plans','catalog','categories','coupons','invitations']},{name:'用户与订单',ids:['customers','orders','manual-payments','tickets']},{name:'内容与支持',ids:['announcements','help']},{name:'系统与维护',ids:['settings','appearance','payment-methods','administrators','telegram','version','jobs','audit','account']}];return sections.map(g=>({name:g.name,items:g.ids.flatMap(id=>tabs.value.filter(t=>t[0]===id))})).filter(g=>g.items.length)});
const title=computed(()=>tabs.value.find(x=>x[0]===page.value)?.[1]||'用户中心');
const editor=ref(''),form=ref<Row>({}),selectedPlan=ref<Row|null>(null),buy=reactive({plan_id:'',price_id:'',coupon:'',request_key:''}),quote=ref<Row|null>(null),thread=ref<Row|null>(null),ticketForm=reactive({subject:'',body:'',images:[] as string[]});
const payOrder=ref<Row|null>(null),serviceTarget=ref(''),deletingCustomer=ref<Row|null>(null),deletedCustomers=ref(false);
const groupsReady=ref(false),deletedPlans=ref(false),removingPlan=ref<Row|null>(null);
const settingsForm=ref<Row>({}),secretForm=ref<Row>({}),paymentForm=ref<Row>({}),allowlist=ref('');
const planFields=computed(()=>fields[editor.value]?.map(f=>f.key==='category_id'?{...f,options:categories.value.map(c=>({value:c.id,label:c.name}))}:f)||[]);
const protocols=computed(()=>[...new Set(groups.value.filter(g=>form.value.group_ids?.includes(g.id)).flatMap(g=>g.services.filter((s:Row)=>s.managed_users).map((s:Row)=>s.protocol)))].sort() as string[]);
const dashboard=ref<Row>({});
const stats=computed(()=>({customers:dashboard.value.current_users,buyers:dashboard.value.current_buying_users,historical:dashboard.value.historical_buying_users,unchecked:dashboard.value.unchecked_buying_users,paid:dashboard.value.recent_paid_amount,pending:dashboard.value.pending_orders}));
async function request(path:string,method='GET',body?:unknown){const res=await fetch('/portal/v1/'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json',...(csrf.value?{'X-CSRF-Token':csrf.value}:{})},body:body===undefined?undefined:JSON.stringify(body)});const data=await res.json().catch(()=>({error:'服务响应格式错误'}));if(!res.ok)throw new Error(data.error||`请求失败 ${res.status}`);return data;}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function load(){if(!user.value){if(branding.value.show_catalog)catalog.value=await request('catalog');return;}if(['account','payment-methods','manual-payments','administrators','telegram','help','jobs','audit'].includes(page.value)||!admin.value&&page.value==='subscription')return;if(page.value==='catalog'){catalog.value=await request('catalog');return;}if(admin.value){
 if(['settings','appearance'].includes(page.value)){const cfg=await request('admin/settings');config.value=cfg;settingsForm.value={...cfg.settings,theme:cfg.settings.theme||'mint'};allowlist.value=(settingsForm.value.email_allowlist||[]).join('\n');const s=cfg.secrets;secretForm.value={control_origin:s.control_origin||'',control_key:'',smtp_host:s.smtp_host||'',smtp_port:s.smtp_port||587,smtp_user:s.smtp_user||'',smtp_password:'',smtp_from:s.smtp_from||''};paymentForm.value={enabled:false,sandbox:false,app_id:'',seller_id:'',mobile:true,...s.alipay,private_key:'',public_key:''};return}
 if(page.value==='version'){[version.value,capacity.value]=await Promise.all([request('admin/version'),request('admin/capacity').catch(e=>({error:String(e)}))]);return}
 if(page.value==='overview'){dashboard.value=user.value?.is_owner?await request('admin/overview'):{};return}
 rows.value=await request('admin/'+page.value+((page.value==='customers'&&deletedCustomers.value||page.value==='plans'&&deletedPlans.value)?'?deleted=1':''));if(page.value==='plans'){categories.value=await request('admin/categories');try{const g=await request('admin/control-groups');groups.value=g.groups||[];groupsReady.value=true}catch(e){groups.value=[];groupsReady.value=false;error.value=String(e)}}
 }else{if(page.value==='overview'){const data=await request('me/service');service.value=data.service;orders.value=await request('orders')}
 if(page.value==='catalog')catalog.value=await request('catalog');if(page.value==='orders')orders.value=await request('orders');

 if(page.value==='tickets')tickets.value=await request('tickets');}}
async function initialize(){try{branding.value=await request('public');document.title=branding.value.title;const me=await request('me');user.value=me.user;csrf.value=me.csrf;await load()}catch(e){if(user.value)error.value=String(e)}
 if(!user.value&&branding.value.show_catalog){if(page.value==='catalog'){try{await load()}catch(e){error.value=String(e)}}else page.value='catalog'}
 const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.has('verify')){auth.token=fragment.get('verify')||'';authMode.value='verify'}if(fragment.has('reset')){auth.token=fragment.get('reset')||'';authMode.value='reset'}if(fragment.has('verify-email')){auth.token=fragment.get('verify-email')||'';authMode.value='verify-email'}if(auth.token){authOpen.value=true;user.value=null;history.replaceState(null,'',location.pathname);}}
async function authenticate(){await run(async()=>{if(['register','reset'].includes(authMode.value)&&auth.password!==auth.password_confirm)throw new Error('两次输入的密码不一致');if(authMode.value==='login'){const data=await request('auth/login','POST',{email:auth.email,password:auth.password});csrf.value=data.csrf;user.value=data.user;auth.password='';authOpen.value=false;page.value=admin.value?'overview':pendingPlan.value?'catalog':'overview';await load();if(pendingPlan.value&&!admin.value){const plan=catalog.value.plans.find((p:Row)=>p.id===pendingPlan.value?.id);if(plan)choose(plan)}pendingPlan.value=null;return}
 const payload=authMode.value==='register'?{email:auth.email,name:auth.name,password:auth.password,invitation:auth.invitation,password_confirm:auth.password_confirm}:authMode.value==='forgot'?{email:auth.email}:['verify','verify-email'].includes(authMode.value)?{token:auth.token}:{token:auth.token,password:auth.password,password_confirm:auth.password_confirm};const d=await request('auth/'+authMode.value,'POST',payload);notice.value=d.message||(d.status==='pending'?'邮箱已验证，请等待管理员审核':'操作成功，请登录');authMode.value='login';auth.password='';auth.password_confirm='';auth.token='';});}
async function logout(){await run(async()=>{await request('auth/logout','POST',{});user.value=null;csrf.value='';authOpen.value=false;page.value=branding.value.show_catalog?'catalog':'overview';await load()})}
function openEditor(kind:string,row?:Row){editor.value=kind;error.value='';form.value=defaults(kind);if(kind==='invitations')form.value.max_uses=1;
 if(row){for(const f of fields[kind]||[]){if(f.key==='quota_gb'){form.value.quota_gb=Number(row.quota_bytes)/(row.quota_unit==='GiB'?1073741824:1e9);continue}let v=row[f.key];if(v!==undefined)form.value[f.key]=f.type==='json'?JSON.stringify(v,null,2):f.type==='datetime-local'?localDate(new Date(v)):v;}for(const k of ['id','version','group_ids','protocols','prices','display_features','images'])if(row[k]!==undefined)form.value[k]=JSON.parse(JSON.stringify(row[k]));}
 else if(kind==='plans')form.value.category_id=categories.value[0]?.id||'';}
async function saveEditor(){await run(async()=>{const payload:Row={};for(const f of fields[editor.value]){if(f.key==='quota_gb')continue;let v=form.value[f.key];if(f.type==='json')v=JSON.parse(v||'[]');if(f.type==='datetime-local')v=new Date(v).toISOString();payload[f.key]=v;}for(const k of ['id','version'])if(form.value[k]!==undefined)payload[k]=form.value[k];if(editor.value==='plans'){payload.quota_bytes=Math.round(Number(form.value.quota_gb)*(form.value.quota_unit==='GiB'?1073741824:1e9));for(const k of ['group_ids','protocols','prices','display_features'])payload[k]=form.value[k];}
 if(editor.value==='announcements')payload.images=form.value.images||[];
 const result=await request('admin/'+editor.value,form.value.id?'PUT':'POST',payload);editor.value='';notice.value=result.notice||'已保存';await load();});}
async function customerStatus(row:Row){await run(async()=>{const d=await request('admin/customers','PUT',{id:row.id,status:row.status==='active'?'disabled':'active'});notice.value=d.notice;await load()})}
function choose(plan:Row){if(!user.value){pendingPlan.value=plan;authOpen.value=true;authMode.value='login';notice.value='登录后继续购买：'+plan.name;return}selectedPlan.value=plan;Object.assign(buy,{plan_id:plan.id,price_id:plan.prices[0]?.id||'',coupon:'',request_key:buyKey()});quote.value=null;}
watch(()=>[buy.price_id,buy.coupon],()=>{quote.value=null;buy.request_key=buyKey()});
async function priceQuote(){await run(async()=>{quote.value=await request('checkout/quote','POST',buy)})}
async function placeOrder(){await run(async()=>{if(!quote.value)return;const d=await request('orders','POST',buy);selectedPlan.value=null;page.value='orders';await load();notice.value='订单已创建，请核对实付金额后支付。订单号：'+d.id})}
function payment(row:Row){payOrder.value=row}
async function cancelOrder(row:Row){await run(async()=>{const d=await request(`orders/${row.id}/cancel`,'POST',{});notice.value=d.message;await load()})}
async function copy(text:string){try{await navigator.clipboard.writeText(text);notice.value='已复制'}catch{notice.value='当前 IP 入口未提供剪贴板权限，请选中链接手动复制'}}
async function showTicket(row:Row){await run(async()=>{const d=await request('tickets/'+row.id);thread.value={...row,...d};ticketForm.body='';ticketForm.images=[]})}
async function sendTicket(close=false){await run(async()=>{if(thread.value)await request('tickets/'+thread.value.id,'POST',{body:ticketForm.body,images:ticketForm.images,close});else await request('tickets','POST',ticketForm);thread.value=null;editor.value='';ticketForm.subject='';ticketForm.body='';ticketForm.images=[];notice.value='工单已保存';await load()})}
async function saveSettings(){await run(async()=>{const s={...settingsForm.value,email_allowlist:allowlist.value.split(/[\n,]/).map(x=>x.trim()).filter(Boolean)};const {private_configured,public_configured,...p}=paymentForm.value;const d=await request('admin/settings','PUT',{settings:s,secrets:{...secretForm.value,alipay:p}});notice.value=d.notice;branding.value=await request('public');document.title=branding.value.title;await load()})}
async function signedOut(message:string){user.value=null;csrf.value='';page.value='overview';authOpen.value=true;await nextTick();notice.value=message}
async function seedDemos(){await run(async()=>{const d=await request('admin/demo-plans','POST',{});notice.value=d.message;await load()})}
async function update(){await run(async()=>{await request('admin/version','POST',{version:version.value.latest,current:version.value.current});notice.value='更新已进入任务队列。请等待健康检查完成；失败将尝试回滚。';await load()})}
let interval:ReturnType<typeof setInterval>,stockTimer:ReturnType<typeof setInterval>;
onMounted(()=>{void initialize();stockTimer=setInterval(()=>{if(document.visibilityState==='visible'&&(user.value||guestCatalog.value)&&page.value==='catalog'&&!busy.value&&!selectedPlan.value)void load().catch(()=>{})},10000);interval=setInterval(()=>{if(document.visibilityState==='visible'&&user.value&&!busy.value&&!editor.value&&!selectedPlan.value&&!thread.value&&!['settings','appearance','catalog'].includes(page.value))void load().catch(()=>{});},30000)});
onUnmounted(()=>{clearInterval(interval);clearInterval(stockTimer)});
watch(page,()=>{usageTarget.value=null;rows.value=[];error.value='';notice.value='';void run(load)});
</script>

<template>
<div class="portal-app" :data-theme="effectiveTheme" :class="{'has-background':desktopBackground||mobileBackground}">
<ResponsiveBackground :key="backgroundReload" v-if="desktopBackground||mobileBackground" :desktop="desktopBackground" :mobile="mobileBackground" :dim="Number(appearance.background_dim)||0"/>
<div v-if="guestCatalog" class="storefront"><header class="store-header"><a class="brand" href="/">✦ <span>{{branding.title}}<small>STARHUB · 连接由你选择</small></span></a><div class="actions"><ThemeSwitch v-model="userTheme"/><button @click="authOpen=true;authMode='login'">登录</button><button v-if="branding.registration_mode!=='closed'" class="primary" @click="authOpen=true;authMode='register'">注册</button></div></header><main><section class="store-hero"><span class="eyebrow">YOUR CONNECTION, YOUR CHOICE</span><h1>连接世界，恰如所需。</h1><p>先看套餐，选好再登录。每份订阅独立管理，流量清晰可查。</p></section><div v-if="error" class="alert error" role="alert">{{error}}</div><PlanCatalog :catalog="catalog" :admin="false" @choose="choose"/><section v-if="branding.announcements?.length" class="panel"><h3>站点公告</h3><article v-for="a in branding.announcements" :key="a.id" class="announcement"><strong><span v-if="a.pinned" class="badge pin-badge">置顶</span> {{a.title}}</strong><p class="pre">{{a.body}}</p><ImageGallery :images="a.images"/></article></section></main><footer>{{branding.title}} · STARHUB</footer></div>
<div v-else-if="!user" class="auth-layout"><section class="intro"><a class="brand" href="/">✦ <span>STARHUB <small>星枢 · 用户中心</small></span></a><div><span class="eyebrow">STAY CONNECTED</span><h1>连接世界，<br>从这里开始。</h1><p>选择适合自己的套餐，<br>流量、订阅与服务，一处掌握。</p><div class="intro-tags"><span>独立身份</span><span>清晰用量</span><span>多端订阅</span></div></div><small>星枢用户中心 · {{branding.version||'加载中'}}</small></section>
<main class="auth-main"><div class="auth-box"><div class="auth-tools"><button v-if="branding.show_catalog&&!auth.token" type="button" @click="authOpen=false">← 浏览套餐</button><ThemeSwitch v-model="userTheme"/></div><span class="eyebrow">WELCOME TO STARHUB</span><h2>{{({login:'欢迎回来',register:'创建账户',forgot:'找回密码',reset:'设置新密码',verify:'验证邮箱','verify-email':'验证新邮箱'} as Row)[authMode]}}</h2><p class="muted">{{authMode==='register'?(branding.registration_mode==='email'?'验证邮箱后完成注册。':'注册需要有效邀请或白名单，并验证邮箱。'):'管理你的订阅与连接服务'}}</p><div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="notice" class="alert" role="status">{{notice}}</div>
<form @submit.prevent="authenticate"><label v-if="!['verify','verify-email','reset'].includes(authMode)">邮箱<input v-model="auth.email" type="email" required autocomplete="username"></label><label v-if="authMode==='register'">昵称<input v-model="auth.name" required maxlength="80"></label><label v-if="['login','register','reset'].includes(authMode)">密码<input v-model="auth.password" type="password" required :minlength="authMode==='login'?1:12" maxlength="256" :autocomplete="authMode==='login'?'current-password':'new-password'"></label><label v-if="['register','reset'].includes(authMode)">再次输入密码<input v-model="auth.password_confirm" type="password" required minlength="12" maxlength="256" autocomplete="new-password"></label><p v-if="['register','reset'].includes(authMode)&&auth.password_confirm&&auth.password!==auth.password_confirm" class="alert error">两次输入的密码不一致</p><label v-if="authMode==='register'&&branding.registration_mode==='invite'">邀请码<input v-model="auth.invitation" required></label><button class="primary full" :disabled="busy||authMode==='register'&&!branding.email_ready||['register','reset'].includes(authMode)&&auth.password!==auth.password_confirm">{{busy?'处理中…':authMode==='login'?'登录':authMode==='verify'?'确认验证邮箱':'提交'}}</button></form><div class="auth-links"><button v-if="authMode!=='login'" @click="authMode='login'">返回登录</button><template v-else><button @click="authMode='forgot'">忘记密码</button><button v-if="branding.registration_mode!=='closed'" @click="authMode='register'">{{branding.registration_mode==='invite'?'使用邀请注册 →':'注册账户 →'}}</button></template></div><small v-if="!branding.email_ready&&authMode==='register'" class="muted">邮箱服务尚未就绪，请联系管理员。</small></div></main></div>

<div v-else class="shell" :class="{'nav-collapsed':navigationState.collapsed&&!navigationState.narrow}"><WorkspaceNav ref="navigation" :groups="navSections" :user="user" :page="page" :admin="admin" :disabled="busy||mediaUploads>0" @navigate="page=$event" @logout="logout" @change="navigationState=$event" @restore-focus="navigationToggle?.focus()"/><main class="content" :inert="navigationState.narrow&&navigationState.open"><header><button ref="navigationToggle" class="navigation-toggle" type="button" aria-label="切换功能导航" aria-controls="workspace-navigation" :aria-expanded="navigationState.narrow?navigationState.open:!navigationState.collapsed" @click="navigation?.toggle()">☰</button><div><div class="eyebrow">STARHUB / {{admin?'ADMINISTRATION':'PERSONAL'}}</div><h1>{{title}}</h1></div><div class="actions"><ThemeSwitch v-model="userTheme"/><button :disabled="busy||mediaUploads>0" @click="run(load)">↻ 刷新</button></div></header><div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="notice" class="alert" role="status">{{notice}}</div>

<template v-if="page==='overview'"><section class="welcome"><div><span class="eyebrow">{{admin?'SERVICE CONSOLE':'YOUR CONNECTION, SIMPLIFIED'}}</span><h2>{{admin?'让每一份服务，清楚可控。':'你好，'+user.name+'。'}}</h2><p>{{admin?'套餐、用户与订单，组成你的运营工作区。':'在这里查看服务状态，管理套餐和多端订阅。'}}</p><button class="primary" @click="page=admin?(can('plans')?'plans':'account'):'catalog'">{{admin?(can('plans')?'管理套餐':'个人账户'):'查看套餐'}} →</button></div><div class="orb">✦</div></section><div class="metrics overview-metrics" v-if="admin&&user.is_owner"><article><span>现有用户</span><strong>{{stats.customers??'—'}}<small> 人</small></strong><small>未删除的注册客户，含待验证及停用账户</small></article><article><span>现有购买用户</span><strong>{{stats.buyers??'—'}}<small> 人</small></strong><small>持有未过期、未停用付费订阅，按用户去重；历史付费 {{stats.historical??'—'}} 人<span v-if="stats.unchecked"> · {{stats.unchecked}} 人状态待同步</span></small></article><article><span>最近订单中的已付金额</span><strong>{{money(stats.paid)}}</strong><small>最近 300 条订单，含待开通</small></article><article><span>待处理订单</span><strong>{{stats.pending}}<small> 笔</small></strong></article></div><p v-if="admin&&user.is_owner&&dashboard.sync_warning" class="alert">{{dashboard.sync_warning}}</p><div class="metrics" v-if="!admin"><article><span>最近订单剩余流量</span><strong>{{service?traffic(service.remaining_bytes,service.quota_unit||'GB'):'未开通'}}</strong></article><article><span>该订单已用 / 配额</span><strong>{{traffic(service?.used_bytes,service?.quota_unit||'GB')}}</strong><small>{{traffic(service?.quota_bytes,service?.quota_unit||'GB')}} / 月</small></article><article><span>该订单服务到期</span><strong class="date">{{date(service?.expires_at)}}</strong><small>下次流量重置：{{date(service?.next_reset_at)}}</small></article></div><section class="panel" v-if="!admin&&service"><div class="section-head"><h3>{{service.plan_name}}</h3><span class="badge">{{states[service.state]||(service.enabled?'服务已开通':'服务已停用')}}</span></div><progress :value="Number(service.used_bytes)||0" :max="Number(service.quota_bytes)||1"/><p class="muted">流量由星枢独立身份计量。显示值随主机回传更新。</p><button @click="page='subscription'">查看全部独立订阅 →</button></section><section class="panel"><h3>服务公告</h3><article v-for="a in branding.announcements" :key="a.id" class="announcement"><div class="announcement-title"><span v-if="a.pinned" class="badge pin-badge">置顶</span><strong>{{a.title}}</strong></div><p class="pre">{{a.body}}</p><ImageGallery :images="a.images"/><small>{{date(a.created_at)}}</small></article><p v-if="!branding.announcements?.length" class="muted">暂无公告</p></section></template>

<PlanCatalog v-if="page==='catalog'" :catalog="catalog" :admin="admin" @choose="choose"/>

<template v-if="page==='orders'"><div class="panel table-wrap"><table><thead><tr><th>订单 / 套餐</th><th v-if="admin">购买用户</th><th>实付</th><th>支付状态</th><th>服务开通</th><th>创建 / 付款期限</th><th>操作</th></tr></thead><tbody><tr v-for="o in admin?rows:orders" :key="o.id"><td><strong>{{o.plan_name||o.snapshot?.plan?.name}}</strong><span v-if="o.renewal_of" class="badge">续费原订阅</span><small class="mono">{{o.id}}</small></td><td v-if="admin">{{o.email}}</td><td>{{money(o.payable)}}<small>优惠 {{money(o.discount_amount)}}</small></td><td><span class="badge" :class="o.state">{{o.manual_state==='submitted'?'待人工核款':states[o.state]}}</span></td><td>{{o.renewal_of?(o.fulfillment==='active'?'续费已生效':states[o.fulfillment]):(states[o.service_state]||states[o.fulfillment])}}</td><td>{{date(o.created_at)}}<small>期限 {{date(o.expires_at)}}</small></td><td><button v-if="!admin&&o.has_subscription&&!o.subscription_hidden" @click="serviceTarget=o.service_id||o.id;page='subscription'">查看此订单订阅</button><small v-if="!admin&&o.subscription_hidden" class="muted">订阅记录已移除，可在订阅页恢复</small><div class="actions" v-if="!admin&&(o.state==='pending'||o.manual_state)"><button class="primary" :disabled="busy||!o.manual_state&&new Date(o.expires_at).getTime()<Date.now()" @click="payment(o)">{{o.manual_state?'查看付款 / 凭证':'选择方式付款'}}</button><button v-if="o.state==='pending'&&o.manual_state!=='submitted'" @click="cancelOrder(o)">取消</button></div><span v-else class="muted">{{o.state==='late_paid'?'请联系管理员处理退款':'—'}}</span></td></tr></tbody></table><div v-if="!(admin?rows:orders).length" class="empty">暂无订单</div></div><p class="muted" v-if="!admin">付款窗口显示管理员已启用的支付宝 / 微信个人收款码或在线支付通道。</p></template>

<SubscriptionsPanel v-if="!admin&&page==='subscription'" :request="request" :initial="serviceTarget" @payment="payment"/><ClientHelp v-if="page==='help'" :request="request" :editable="admin&&can('content')"/>

<template v-if="page==='tickets'"><section class="panel"><div class="section-head"><h3>{{admin?'用户工单':'我的工单'}}</h3><button v-if="!admin" @click="thread=null;editor='ticket'">＋ 创建工单</button></div><div v-for="t in admin?rows:tickets" :key="t.id" class="list-row"><div><strong>{{t.subject}}</strong><small>{{t.email||date(t.created_at)}}</small></div><span class="badge">{{states[t.state]}}</span><button @click="showTicket(t)">查看 / 回复</button></div><p class="empty" v-if="!(admin?rows:tickets).length">暂无工单</p></section></template>

<template v-if="admin&&page==='customers'"><div class="section-head"><p class="muted">删除会注销登录并排队撤销全部订单代理权限，保留核账记录。</p><label class="multi" v-if="can('delete_customers')"><input type="checkbox" v-model="deletedCustomers" @change="run(load)">显示已删除用户</label></div><div class="panel table-wrap"><table><thead><tr><th>用户</th><th>状态</th><th>注册时间</th><th>操作</th></tr></thead><tbody><tr v-for="c in rows" :key="c.id"><td><strong>{{c.name}}</strong><small>{{c.email}}</small><small class="mono">{{c.id}}</small></td><td>{{c.deleted_at?'已删除':states[c.status]}}</td><td>{{date(c.created_at)}}</td><td><div class="actions"><button v-if="!c.deleted_at&&c.role!=='admin'&&c.email_verified_at" @click="customerStatus(c)" :disabled="busy">{{c.status==='active'?'停用账户与代理权限':'批准 / 启用'}}</button><button v-if="can('delete_customers')" :disabled="busy" @click="deletingCustomer=c">{{c.deleted_at?'恢复用户':'删除用户'}}</button></div></td></tr></tbody></table></div></template>

<AccountPanel v-if="page==='account'" :request="request" :user="user" @update="user=$event" @signed-out="signedOut"/><PaymentOptions v-if="admin&&page==='payment-methods'" :request="request"/><TelegramPanel v-if="admin&&page==='telegram'" :request="request"/><AdminReview v-if="admin&&page==='manual-payments'" :request="request"/><AdminTeam v-if="admin&&page==='administrators'" :request="request"/>
<template v-if="admin&&fields[page]"><div class="section-head"><p class="muted">{{page==='plans'?'绑定现有星枢用户组，并选择套餐允许的独立计费协议。':'保存历史记录；不再使用的条目可编辑停用。'}}</p><div class="actions"><label v-if="page==='plans'" class="multi"><input type="checkbox" v-model="deletedPlans" @change="run(load)">显示已删除套餐</label><button v-if="page==='plans'&&user.is_owner" @click="seedDemos" :disabled="busy">生成示例套餐</button><button class="primary" @click="openEditor(page)">＋ 新建{{title.replace('管理','')}}</button></div></div><div class="panel"><div v-for="r in rows" :key="r.id" class="list-row managed-row"><div><strong>{{r.name||r.title||r.prefix}} <span v-if="r.simulation" class="badge">模拟</span><span v-if="r.pinned" class="badge pin-badge">置顶 · {{r.pin_order}}</span></strong><small v-if="r.description">{{r.description}}</small><small class="mono">{{r.id}}</small><small v-if="page==='plans'">{{traffic(r.quota_bytes,r.quota_unit||'GB')}} / 月 · 已选协议：{{(groupsReady?configuredProtocols(r,groups):r.protocols||[]).map((p:string)=>p.toUpperCase()).join(' / ')||'无'}}{{groupsReady?'':'（待核验）'}}</small><small v-if="page==='plans'">有效人数占用 {{r.effective_members??0}} / {{r.stock>0?r.stock:'不限'}} · {{r.policy_pending?('节点权限待同步 '+r.policy_pending+' 份'):'节点权限已同步'}}<span v-if="r.policy_failed"> · 同步失败 {{r.policy_failed}} 份，可在后台任务中重试</span></small><div v-if="page==='coupons'" class="code-line"><code>{{r.code}}</code><button @click="copy(r.code)">复制优惠码</button></div><small v-if="page==='coupons'">剩余 {{r.remaining_uses??'不限'}} 次 · 已占用 {{r.used_uses??0}} / {{r.max_uses||'不限'}} · 待付款 {{r.reserved_uses??0}} 次</small><small v-if="page==='coupons'">{{r.code}} · {{date(r.starts_at)}} — {{date(r.ends_at)}}</small><div v-if="page==='invitations'" class="code-line"><code v-if="r.code">{{r.code}}</code><small v-else>旧邀请码未保存原文，可编辑生成新码。</small><button v-if="r.code" @click="copy(r.code)">复制邀请码</button></div><small v-if="page==='invitations'">剩余 {{r.remaining_uses??Math.max(0,r.max_uses-r.claimed)}} 次 · 已占用 {{r.claimed}} / {{r.max_uses}} · 已验证 {{r.verified_uses??0}} 次 · {{r.email||'不限邮箱'}}</small></div><span class="badge">{{r.deleted_at?'已删除':r.enabled?'已启用':'已停用'}}</span><div class="actions"><button v-if="page==='coupons'||page==='invitations'" @click="usageTarget={...r,kind:page}">使用记录</button><button v-if="!r.deleted_at" @click="openEditor(page,r)">编辑</button><button v-if="page==='plans'" @click="removingPlan=r">{{r.deleted_at?'恢复':'删除套餐'}}</button></div></div><div v-if="!rows.length" class="empty">暂无内容，点击右上角创建。</div></div></template>

<template v-if="admin&&page==='appearance'&&config"><form @submit.prevent="saveSettings"><AppearanceSettings :model="settingsForm" :request="request" @retry="backgroundReload++" @busy="mediaBusy"/><button class="primary" :disabled="busy||mediaUploads>0">保存外观设置</button></form></template>
<template v-if="admin&&page==='settings'&&config"><div class="settings-tabs" role="tablist" aria-label="系统设置分类"><button v-for="t in [['access','网站入口'],['registration','注册与访问'],['control','星枢连接'],['guide','套餐说明'],['mail','邮件服务'],['alipay','官方支付']]" :key="t[0]" :class="{selected:settingsTab===t[0]}" @click="settingsTab=t[0]!" role="tab" :aria-selected="settingsTab===t[0]">{{t[1]}}</button></div><form @submit.prevent="saveSettings"><section class="panel" v-show="settingsTab==='access'"><h3>品牌与访问入口</h3><div class="fields"><label>站点名称<input v-model="settingsForm.title" required maxlength="40"></label><label>流量显示<select v-model="settingsForm.traffic_unit"><option>GB</option><option>GiB</option><option value="auto">自动</option></select></label><label>独立域名（可选）<input v-model="settingsForm.domain" placeholder="portal.example.com"></label><label>公网入口<input v-model="settingsForm.public_origin" placeholder="http://IP:18088"></label><label class="check">域名开启 HTTPS<input type="checkbox" v-model="settingsForm.https"></label></div><p class="muted">未绑定域名时使用 IP＋端口。同机已有星枢且此域名证书就绪时，会自动关联到本购买面板的反代；其他宝塔 / Nginx 生成本站反代片段供现有平台应用。证书就绪不代表反代已生效，任务页会校验真实入口。</p></section><section class="panel" v-show="settingsTab==='access'"><h3>域名同步检查</h3><p class="muted">首次绑定或修复已有反代后，可重试配置；无需改动设置或重新连接 VPS。</p><button type="button" :disabled="busy" @click="run(async()=>{const d=await request('admin/gateway/retry','POST',{});notice=d.message})">重试域名配置 / 检查入口</button></section><section class="panel" v-show="settingsTab==='registration'"><h3>注册管控</h3><div class="fields"><label>注册模式<select v-model="settingsForm.registration_mode"><option value="closed">关闭注册</option><option value="invite">邀请码＋邮箱验证</option><option value="allowlist">白名单＋邮箱验证</option><option value="email">直接邮箱验证注册</option></select></label><label>总注册上限<input type="number" v-model.number="settingsForm.registration_limit" min="1" max="500"></label><label class="check">验证后需要管理员审核<input type="checkbox" v-model="settingsForm.approval_required"></label><label class="check">未登录可查看套餐<input type="checkbox" v-model="settingsForm.show_catalog"></label><label class="wide">邮箱白名单<textarea v-model="allowlist" rows="3" placeholder="一行一个邮箱或 @example.com；邀请模式下也可叠加限制"></textarea></label></div></section><section class="panel" v-show="settingsTab==='control'"><h3>星枢 API 连接 <span class="badge">{{config.secrets.control_configured?'已保存密钥':'待配置'}}</span></h3><div class="fields"><label>星枢 HTTPS 地址<input v-model="secretForm.control_origin" placeholder="https://vps.example.com"></label><label>受限 API 密钥<input type="password" v-model="secretForm.control_key" autocomplete="new-password" placeholder="留空保留原值"></label></div><p class="muted">需要 commerce:read、commerce:write、users:read、subscriptions:read、subscriptions:links、profiles:read、devices:read。请使用单独的购买面板 API 密钥。</p></section><section class="panel" v-show="settingsTab==='guide'"><h3>购买与续费说明</h3><p class="muted">同时用于游客套餐首页、用户选购套餐和管理员预览。仅修改展示文字，不会改变实际续费、销售名额或计费规则。</p><label>说明标题<input v-model="settingsForm.catalog_guide_title" maxlength="80" placeholder="购买与续费说明"></label><label>说明正文<textarea v-model="settingsForm.catalog_guide_body" maxlength="6000" rows="7" placeholder="填写购买、续费及服务须知，支持换行"></textarea></label><button type="button" @click="settingsForm.catalog_guide_title=defaultCatalogGuide.title;settingsForm.catalog_guide_body=defaultCatalogGuide.body">恢复默认文案</button><p class="muted">留空保存时恢复默认内容。保存后，当前打开的套餐页将在下一轮刷新时更新。</p><details class="guide-preview"><summary>{{settingsForm.catalog_guide_title||defaultCatalogGuide.title}}</summary><p class="pre">{{settingsForm.catalog_guide_body||defaultCatalogGuide.body}}</p></details></section><section class="panel" v-show="settingsTab==='mail'"><h3>验证邮件 SMTP</h3><div class="fields"><label>SMTP 主机<input v-model="secretForm.smtp_host"></label><label>安全端口<select v-model.number="secretForm.smtp_port"><option :value="465">465 · TLS</option><option :value="587">587 · STARTTLS</option></select></label><label>登录用户名<input v-model="secretForm.smtp_user"></label><label>邮箱密码 / 授权码<input v-model="secretForm.smtp_password" type="password" placeholder="留空保留原值" autocomplete="new-password"></label><label>发件邮箱<input type="email" v-model="secretForm.smtp_from"></label></div></section><section class="panel" v-show="settingsTab==='alipay'"><h3>支付宝在线支付（可选）</h3><p class="muted">使用个人支付宝或微信收款码，请在左侧「收款方式」上传图片；不需要启用本在线通道。</p><div class="fields"><label>应用 APP ID<input v-model="paymentForm.app_id"></label><label>商户 Seller ID<input v-model="paymentForm.seller_id"></label><label>商户应用私钥 PEM<textarea v-model="paymentForm.private_key" rows="4" placeholder="留空保留原值" spellcheck="false"></textarea></label><label>支付宝公钥 PEM<textarea v-model="paymentForm.public_key" rows="4" placeholder="留空保留原值" spellcheck="false"></textarea></label><label class="check">启用支付<input type="checkbox" v-model="paymentForm.enabled"></label><label class="check">沙箱环境<input type="checkbox" v-model="paymentForm.sandbox"></label><label class="check">移动网页支付<input type="checkbox" v-model="paymentForm.mobile"></label></div><p class="muted">启用前需配置可达的 HTTPS 回调入口和已获准的支付宝应用。付款结果以签名回调与主动查询为准。当前回调：{{settingsForm.public_origin}}/portal/v1/payments/alipay/notify</p></section><button class="primary" :disabled="busy||mediaUploads>0">保存设置</button></form></template>

<template v-if="admin&&page==='version'"><section class="panel"><span class="eyebrow">SYSTEM UPDATE</span><h2>保持服务，持续向前。</h2><div class="metrics"><article><span>当前版本</span><strong>v{{version.current}}</strong></article><article><span>最新正式版</span><strong>{{version.latest?'v'+version.latest:'尚未读取'}}</strong></article><article><span>本机更新助手</span><strong class="date">{{version.helper_ready?'在线':'离线 / 未安装'}}</strong></article></div><p class="muted">{{version.message||'更新前备份数据库，验证正式分发包校验值，启动失败自动恢复。更新本购买面板；同机星枢会请求本版所需的官方兼容更新。'}}</p><div class="actions"><button @click="run(load)">检查版本</button><button class="primary" @click="update" :disabled="busy||!version.available||!version.helper_ready">更新到 v{{version.latest||'—'}}</button><a v-if="version.release_url" :href="version.release_url" target="_blank" rel="noreferrer">查看发行说明 ↗</a></div></section><section class="panel"><h3>资源与接入容量</h3><p v-if="capacity.error" class="muted">{{capacity.error}}</p><div class="metrics"><article><span>星枢现存身份 / 实现上限</span><strong>{{capacity.identities??'—'}} / {{capacity.identity_limit??'—'}}</strong><small>包括星枢中的其他身份；不包含已删除身份，也不代表并发承载</small></article><article><span>已核验订单 / 当前有效订阅</span><strong>{{capacity.paid_orders??'—'}} / {{capacity.portal_services??'—'}}</strong></article></div><p class="muted">购买用户 {{capacity.registered_customers??'—'}} 人 · 失效服务 {{capacity.invalid_services??'—'}} 份 · 待同步 {{capacity.unchecked_services??'—'}} 份。最近验证：{{date(capacity.services_checked_at)}}。有效订阅仅计已付款且星枢身份启用、未过期、额度可用的服务。</p><p v-if="capacity.sync_warning" class="alert">{{capacity.sync_warning}}</p><div class="resource-grid"><p>应用 <strong>{{version.helper_status?.app_resources||'等待采样'}}</strong></p><p>数据库 <strong>{{version.helper_status?.db_resources||'等待采样'}}</strong></p><p>安装盘可用 / 总容量 <strong>{{version.helper_status?.disk_available||'等待采样'}}</strong></p><p>星枢兼容状态 <strong>{{version.helper_status?.control_compatibility||'等待检查'}}</strong></p></div><p class="muted">应用容器上限 256 MiB，数据库 512 MiB，资源每分钟采样。用户数量与并发承载需结合节点、数据库延迟及实际负载评估，不自动放开内核身份上限。</p></section><section class="panel"><h3>更新与域名任务</h3><div class="list-row" v-for="j in version.jobs" :key="j.id"><div><strong>{{j.kind==='update'?'版本更新':'域名配置'}} · {{j.subject}}</strong><small>{{j.detail||date(j.created_at)}}</small></div><span class="badge">{{states[j.state]}}</span></div></section></template>

<OperationalHistory v-if="admin&&(page==='jobs'||page==='audit')" :key="page" :request="request" :kind="page"/>
<AccountDeletion v-if="deletingCustomer" :request="request" :target="deletingCustomer" kind="customers" @close="deletingCustomer=null" @changed="(message:string)=>{deletingCustomer=null;notice=message;void load()}"/><footer>STARHUB PORTAL <span>✦</span> {{branding.title}} · v{{branding.version||'加载中'}}</footer></main></div>

<ConfirmRecordAction v-if="removingPlan" :request="request" :path="removingPlan.deleted_at?'admin/plans/restore':'admin/plans'" :method="removingPlan.deleted_at?'POST':'DELETE'" :payload="{id:removingPlan.id,version:removingPlan.version}" :title="removingPlan.deleted_at?'恢复套餐':'删除套餐'" :message="removingPlan.name+'\n'+(removingPlan.deleted_at?'恢复后默认下架，请编辑核对后上架。':'此套餐将从销售列表移除，已有订阅、订单和付款记录保留；可在已删除套餐中恢复。')" @close="removingPlan=null" @changed="(msg:string)=>{removingPlan=null;notice=msg;void load()}"/>
<OrderPayment v-if="payOrder" :order="payOrder" :request="request" @close="payOrder=null" @changed="load"/>
<CodeUsage v-if="usageTarget" :key="usageTarget.id" :kind="usageTarget.kind" :target="usageTarget" :request="request" @close="usageTarget=null"/><div v-if="editor||selectedPlan||thread" class="modal-backdrop" @click.self="closeModal"><section class="modal" role="dialog" aria-modal="true" :aria-label="selectedPlan?'确认套餐':thread?'工单':'编辑内容'"><div class="section-head"><h2>{{selectedPlan?'确认套餐':thread?'工单 · '+thread.subject:editor==='ticket'?'创建工单':(form.id?'编辑':'新建')+title}}</h2><button @click="closeModal" :disabled="mediaUploads>0" aria-label="关闭">×</button></div><div v-if="error" class="alert error">{{error}}</div>
<template v-if="selectedPlan"><h3>{{selectedPlan.name}}</h3><label>购买周期<select v-model="buy.price_id"><option v-for="p in selectedPlan.prices" :value="p.id" :key="p.id">{{p.months}} 个月 · {{money(p.amount)}}</option></select></label><label>优惠码（可选）<input v-model="buy.coupon" maxlength="32"></label><button @click="priceQuote" :disabled="busy">核算价格</button><div v-if="quote" class="quote"><div>原价 <strong>{{money(quote.base_amount)}}</strong></div><div>优惠 <strong>−{{money(quote.discount_amount)}}</strong></div><div>实付 <strong>{{money(quote.payable)}}</strong></div><small>付款期限：{{date(quote.expires_at)}}。创建订单时会重新校验活动名额。</small><button class="primary full" @click="placeOrder" :disabled="busy">创建订单</button></div></template>
<template v-else-if="thread||editor==='ticket'"><div v-for="m in thread?.messages||[]" :key="m.id" class="message"><small>{{m.name}} · {{m.role==='admin'?'管理员':'用户'}} · {{date(m.created_at)}}</small><p class="pre">{{m.body}}</p><ImageGallery :images="m.images"/></div><form @submit.prevent="sendTicket()"><label v-if="!thread">标题<input v-model="ticketForm.subject" required maxlength="120"></label><label>内容<textarea v-model="ticketForm.body" :required="!ticketForm.images.length" maxlength="6000" rows="5"/></label><ImagePicker v-model="ticketForm.images" scope="ticket" :request="request" @busy="mediaBusy"/><div class="actions"><button class="primary" :disabled="busy||mediaUploads>0">发送</button><button v-if="thread?.state==='open'" type="button" @click="sendTicket(true)" :disabled="busy">关闭工单</button></div></form></template>

<form v-else @submit.prevent="saveEditor"><Fields :fields="planFields" :model="form"/><section v-if="editor==='announcements'" class="feature-editor"><h3>公告图片</h3><ImagePicker v-model="form.images" scope="announcement" :request="request" @busy="mediaBusy"/></section><template v-if="editor==='plans'"><section class="feature-editor"><div class="section-head"><h3>套餐展示信息</h3><button type="button" :disabled="form.display_features.length>=12" @click="form.display_features.push({label:'',value:''})">＋ 添加信息</button></div><p class="muted">例如“峰值速率 / 500 Mbps”“适用场景 / 日常浏览与影音”。最多 12 条，仅用于介绍，不改变真实限速或计费。</p><div class="feature-edit-row" v-for="(f,i) in form.display_features" :key="i"><label>名称<input v-model="f.label" maxlength="24" required placeholder="峰值速率"></label><label>内容<input v-model="f.value" maxlength="160" required placeholder="500 Mbps"></label><button type="button" @click="form.display_features.splice(i,1)" :aria-label="'删除展示信息 '+(Number(i)+1)">移除</button></div></section><p v-if="form.simulation" class="alert">模拟套餐仅展示，不接受真实下单；关闭模拟前请确认用户组、协议、价格及配额。</p><PlanProtocolPicker :model="form" :groups="groups" :ready="groupsReady"/><h3>购买周期与价格</h3><div v-for="(p,i) in form.prices" :key="i" class="price-row"><label>周期 ID<input v-model="p.id" pattern="[A-Z0-9_-]{4,32}" required></label><label>月数<input type="number" v-model.number="p.months" min="1" max="12" required></label><label>价格（分）<input type="number" v-model.number="p.amount" min="1" required></label><label>启用<input type="checkbox" v-model="p.enabled"></label><button type="button" @click="form.prices.splice(i,1)" :disabled="form.prices.length===1">移除</button></div><button type="button" @click="form.prices.push({id:'YEAR',months:12,amount:10000,enabled:true})">＋ 添加周期</button></template><div class="modal-actions"><button type="button" @click="editor=''" :disabled="mediaUploads>0">取消</button><button class="primary" :disabled="busy||mediaUploads>0">{{busy?'保存中…':'保存'}}</button></div></form></section></div>
</div>
</template>
